/* HEXA BATTLEGROUNDS upgrade — PART 20 OF 28. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-movie-0', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🚢 🧊 💔","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🦁 👑","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦖 🏞️ 🚙","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["TITANIC"]},{"label":"Film 2 (Decoder)","accept":["THELIONKING","LIONKING"]},{"label":"Film 3 (Intel)","accept":["JURASSICPARK","JURASSICWORLD"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'TITANIC: ship, iceberg, heartbreak | THE LION KING: lion + crown | JURASSIC PARK: dinosaur park', null, 25, 'published'), ('mission-movie-1', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🥋 🐼","mono":false,"big":true},"decoder":{"title":"Film 2","body":"❄️ 👸 ⛄","mono":false,"big":true},"intel":{"title":"Film 3","body":"🕷️ 👨 🏙️","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["KUNGFUPANDA"]},{"label":"Film 2 (Decoder)","accept":["FROZEN"]},{"label":"Film 3 (Intel)","accept":["SPIDERMAN"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'KUNG FU PANDA: kung fu + panda | FROZEN: ice queen + snowman | SPIDERMAN: spider + man', null, 25, 'published'), ('mission-movie-2', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🔍 🐠","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🧸 📖","mono":false,"big":true},"intel":{"title":"Film 3","body":"3️⃣ 🤪 🎓","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["FINDINGNEMO","NEMO"]},{"label":"Film 2 (Decoder)","accept":["TOYSTORY"]},{"label":"Film 3 (Intel)","accept":["3IDIOTS","THREEIDIOTS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'FINDING NEMO: finding + fish | TOY STORY: toy + story | 3 IDIOTS: three idiots at college', null, 25, 'published'), ('mission-movie-3', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🤼‍♀️ 👨‍👧‍👧 🥇","mono":false,"big":true},"decoder":{"title":"Film 2","body":"⚡ 🧙‍♂️ 👓","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦈 🌊 🏊","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["DANGAL"]},{"label":"Film 2 (Decoder)","accept":["HARRYPOTTER"]},{"label":"Film 3 (Intel)","accept":["JAWS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'DANGAL: wrestling father and daughters | HARRY POTTER: scar, wizard, glasses | JAWS: shark attack', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
